SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$LOA TLPI 01/2026 s7 (replacing part of Table 5.7:1) Class 10 building work / All Zones$q$, 'LEVEL_OF_ASSESSMENT', $q$Construction of a Class 10a building (as defined by the Building Code of Australia) If: (i) on the same site as a Heritage place identified in SC6.6.2 of Planning Scheme Policy No. 6; or (ii) on the same site as a Neighbourhood character place identified in SC6.7.2 of Planning Scheme Policy No. 7; or (iii) in the Rural Residential Zone and the gross floor area of all Class 10a buildings (both existing and proposed) on the site would be greater than 10% of the site area. || Building Work that is: a) not listed elsewhere in this table; and b) not associated with a development permit for a Material Change of Use. | The applicable zone code.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/1/plan-and-build/planning-for-our-region/planning-scheme/2025-documents/planning-scheme-amendments/temporary-local-planning-instrument-tlpi-01-2026-table-of-assessment-for-building-works.pdf$q$, $q$Level: Accepted development subject to requirements (TLPI 01/2026) / Code assessment / otherwise Accepted development. Conditions: Class 10a on the same site as a Heritage place or Neighbourhood character place, or in the RR zone where total Class 10a GFA > 10% of site area; other building work not associated with an MCU permit is assessed against "the applicable zone code"$q$, NULL);
