SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 9.3.10:1 AO4.1; Table 9.3.10:2 (Side)$q$, 'TABLE', $q$Table 9.3.10:2 Minimum Front, Side and Rear Boundary Setbacks | Boundary | Qualification | Lot Width | Minimum Setback || Side | Where the building height is greater than 8.5 metres. | Any | 2 metres plus 0.5 metres for every 3 metres or part thereof exceeding 8.5 metres. || Where the building height is 8.5 metres or less. | ≤ 12.5 metres | 1.2m unless external walls built to boundary (zero lot alignment with no gap to boundary) || > 12 metres | 1.2 metre$q$, 'VERIFIED_VERBATIM', $q$Table at printed p117 / PDF p117 (AO4.1 at p104-105)$q$, NULL, $q$Small Lot Housing Design Code (9.3.10)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/1/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-09-development-codes-v29.pdf$q$, $q$Schedule 1 SC1.2: "setback, for a building or structure, means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is."$q$, $q$trc_slh_t2_side$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_slh_t2_side", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.SIDE", "title": "Table 9.3.10:1 AO4.1; Table 9.3.10:2 (Side)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "height<=8.5: 1.2; height>8.5: 2 + 0.5*ceil((h-8.5)/3)", "extracted_value": 1.2, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}, {"level": "ZONE", "zone": "TRC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "TRC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "trc_slh_t2_side", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_setback\", \"operator\": \"conditional\", \"value\": 1.2, \"unit\": \"m\", \"conditions\": [\"building height <= 8.5 m: 1.2 m (lot width <= 12.5 m: 1.2 m unless external walls built to boundary)\", \"building height > 8.5 m: 2 m plus 0.5 m for every 3 m or part thereof exceeding 8.5 m\"], \"exceptions\": [\"lot width <= 12.5 m: external walls may be built to boundary (zero lot alignment)\"], \"formula_text\": \"height<=8.5: 1.2; height>8.5: 2 + 0.5*ceil((h-8.5)/3)\"}\nLot conditions (not encoded): lots < 450 m2\nStructure scope 'Development / buildings' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: YES - Part 1 Table 1.6.1 item 7 (alternative to QDC MP1.1 P2) and code note \"AO 4.1 is an alternative provision for P2 within QDC Part MP1.1\"\nResearcher notes: Small Lot Housing Design Code applies to dwelling houses on lots < 450 m2 in the Low Density Residential and Low-medium Density Residential zones (accepted development subject to requirements under Tables 5.5:1 and 5.5:2 where not in a Schedule 7 plan of development). Scheme drafting error: AO4.1 says \"Table 9.3.10:3\" (which is the built-to-boundary wall length table); the setback table is 9.3.10:2. Lot-width bands overlap (\"≤ 12.5 metres\" vs \"> 12 metres\") as printed."}$q$::jsonb);
