SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 6.2.1:3 PO9/AO9.1$q$, 'ACCEPTABLE_OUTCOME', $q$AO9.1 Where the site has frontage to a collector or local road, buildings are set back from that frontage: (a) within 20% of the average front setback of adjoining buildings; or (b) where there are no adjoining buildings, 4m.$q$, 'VERIFIED_VERBATIM', $q$printed p17 / PDF p17$q$, NULL, $q$Low Density Residential Zone Code (6.2.1)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/2/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-06-zone-codes-v29.pdf$q$, $q$Schedule 1 SC1.2: "setback, for a building or structure, means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is."$q$, $q$trc_ldr_ao9_1_front$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_ldr_ao9_1_front", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.1:3 PO9/AO9.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "AO9.1 Where the site has frontage to a collector or local road, buildings are set back from that frontage: (a) within 20% of the average front setback of adjoining buildings; or (b) where there are no adjoining buildings, 4m.", "extracted_value": 4, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}, {"level": "ZONE", "zone": "TRC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "trc_ldr_ao9_1_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_front_setback\", \"operator\": \"conditional\", \"value\": 4, \"unit\": \"m\", \"conditions\": [\"frontage to a collector or local road\", \"where adjoining buildings: within 20% of the average front setback of adjoining buildings\", \"no adjoining buildings: 4 m\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): code assessable dwelling house only (lots < 450 m2 or hatchet lots not complying with the Small Lot Housing Design Code / Medium Density Residential Code AOs)\nStructure scope 'buildings' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - not listed in Part 1 Table 1.6.1 (only Small Lot Housing Design Code AO3.1, AO4.1, AO7.1/7.2, AO8.1/8.2, AO9.1, AO12.1 are listed); ordinary planning benchmark\nResearcher notes: Table 6.2.1:3 is \"assessment benchmarks for assessable development\" only. A dwelling house on a lot >= 450 m2 (not hatchet, not in a Schedule 7 plan) is accepted development with no benchmarks (Table 5.5:1), so this applies only when a dwelling house becomes code assessable. Class 10 building work not associated with an MCU is accepted subject to requirements against \"the applicable zone code\" (TLPI 01/2026), but Table 6.2.1:1 has no setback AO."}$q$::jsonb);
