SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 6.2.1:3 AO9.2(a)$q$, 'ACCEPTABLE_OUTCOME', $q$AO9.2 Where the site has frontage to a road other than a collector or local road: (a) residential buildings are set back from that frontage in accordance with the requirements of the Queensland Development Code.$q$, 'VERIFIED_VERBATIM', $q$printed p17 / PDF p17$q$, NULL, $q$Low Density Residential Zone Code (6.2.1)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/2/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-06-zone-codes-v29.pdf$q$, NULL, $q$trc_ldr_ao9_2_front_qdc$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_ldr_ao9_2_front_qdc", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.1:3 AO9.2(a)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "QDC road setback applies", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}, {"level": "ZONE", "zone": "TRC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "trc_ldr_ao9_2_front_qdc", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_front_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"frontage to a road other than a collector or local road\"], \"exceptions\": [], \"formula_text\": \"QDC road setback applies\"}\nLot conditions (not encoded): code assessable dwelling house only; frontage to a road other than a collector or local road\nStructure scope 'residential buildings' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - defers to the QDC\nResearcher notes: Defers to QDC. Same applicability limits as trc_ldr_ao9_1_front."}$q$::jsonb);
