SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 6.2.1:3 PO10/AO10.1$q$, 'ACCEPTABLE_OUTCOME', $q$AO10.1 Buildings are set back from a side boundary: (a) Ground Floor (up to 3.5m high) – 1.5m; and (b) First floor (up to 7.5m high) – 2m; (c) Above 7.5m – 3m; or (d) the distance of the height of the retaining wall on the side boundary or combination of the height of the retaining wall and a fence, whichever is greater (Figure 1). Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall.$q$, 'VERIFIED_VERBATIM', $q$printed p18 / PDF p18$q$, NULL, $q$Low Density Residential Zone Code (6.2.1)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/2/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-06-zone-codes-v29.pdf$q$, $q$Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall. Schedule 1 SC1.2: "setback, for a building or structure, means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is."$q$, $q$trc_ldr_ao10_1_side$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_ldr_ao10_1_side", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.SIDE", "title": "Table 6.2.1:3 PO10/AO10.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "AO10.1 Buildings are set back from a side boundary: (a) Ground Floor (up to 3.5m high) – 1.5m; and (b) First floor (up to 7.5m high) – 2m; (c) Above 7.5m – 3m; or (d) the distance of the height of the retaining wall on the side boundary or combination of the height of the retaining wall and a fence, whichever is greater (Figure 1). Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall.", "extracted_value": 1.5, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}, {"level": "ZONE", "zone": "TRC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "trc_ldr_ao10_1_side", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_setback\", \"operator\": \"conditional\", \"value\": 1.5, \"unit\": \"m\", \"conditions\": [\"height <= 3.5 m (ground floor): 1.5 m\", \"height <= 7.5 m (first floor): 2 m\", \"height > 7.5 m: 3 m\", \"or the height of the retaining wall (or retaining wall + fence) on the side boundary, whichever is greater\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): code assessable dwelling house only\nStructure scope 'Buildings' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - not listed in Part 1 Table 1.6.1 (only Small Lot Housing Design Code AO3.1, AO4.1, AO7.1/7.2, AO8.1/8.2, AO9.1, AO12.1 are listed); ordinary planning benchmark\nResearcher notes: Assessable-only table; see trc_ldr_ao9_1_front notes. AO10.3/AO10.4 (non-residential development) not recorded."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$TRC.trc_ldr_ao10_1_side@2026-07-21$q$;
SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 6.2.1:3 PO10/AO10.2$q$, 'ACCEPTABLE_OUTCOME', $q$AO10.2 Buildings are set back: (a) a minimum of 3m from a rear boundary; or (b) the distance equivalent to of the cumulative height of the retaining wall and fence on the rear boundary (Figure 1). Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall.$q$, 'VERIFIED_VERBATIM', $q$printed p18 / PDF p18$q$, NULL, $q$Low Density Residential Zone Code (6.2.1)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/2/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-06-zone-codes-v29.pdf$q$, $q$Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall.$q$, $q$trc_ldr_ao10_2_rear$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_ldr_ao10_2_rear", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.REAR", "title": "Table 6.2.1:3 PO10/AO10.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": 3, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}, {"level": "ZONE", "zone": "TRC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "trc_ldr_ao10_2_rear", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_rear_setback\", \"operator\": \">=\", \"value\": 3, \"unit\": \"m\", \"conditions\": [\"or the cumulative height of the retaining wall and fence on the rear boundary\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): code assessable dwelling house only\nStructure scope 'Buildings' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - not listed in Part 1 Table 1.6.1 (only Small Lot Housing Design Code AO3.1, AO4.1, AO7.1/7.2, AO8.1/8.2, AO9.1, AO12.1 are listed); ordinary planning benchmark\nResearcher notes: Assessable-only table; see trc_ldr_ao9_1_front notes."}$q$::jsonb);
