SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 6.2.2:3 PO9/AO9.1 and Table 1$q$, 'ACCEPTABLE_OUTCOME', $q$AO9.1 Buildings are set back from the road frontage: (a) within 10% of the average front setback of existing residential buildings within 100m of the site; or (b) where there are no adjoining buildings the front setback is provided in accordance with Table 1. || Table 1 | Building element | Minimum setback || Solid building wall (other than a garage) | 4.0m || Solid building wall (where for a garage) | 5.5m || Permeable or non-enclosed elements (e.g. porch, verandah, balcony or carport) | 3.5m (or 3m where secondary road frontage)$q$, 'VERIFIED_VERBATIM', $q$printed p35 / PDF p35$q$, NULL, $q$Low-medium Density Residential Zone Code (6.2.2)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/2/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-06-zone-codes-v29.pdf$q$, $q$Note to PO9: "The prevailing setback of the street is determined by the setbacks of the buildings on any lot along the road within 100m of the site." Schedule 1 SC1.2: "setback, for a building or structure, means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is."$q$, $q$trc_lmdr_ao9_1_front$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_lmdr_ao9_1_front", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.2:3 PO9/AO9.1 and Table 1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "AO9.1 Buildings are set back from the road frontage: (a) within 10% of the average front setback of existing residential buildings within 100m of the site; or (b) where there are no adjoining buildings the front setback is provided in accordance with Table 1. || Table 1 | Building element | Minimum setback || Solid building wall (other than a garage) | 4.0m || Solid building wall (where for a garage) | 5.5m || Permeable or non-enclosed elements (e.g. porch, verandah, balcony or carport) | 3.5m (or 3m where secondary road frontage)", "extracted_value": 5.5, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}, {"level": "ZONE", "zone": "TRC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A"], "sources": [{"key": "trc_lmdr_ao9_1_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_front_setback\", \"operator\": \"conditional\", \"value\": 5.5, \"unit\": \"m\", \"conditions\": [\"within 10% of the average front setback of existing residential buildings within 100 m\", \"no adjoining buildings: garage 5.5 m; carport/non-enclosed 3.5 m (3 m secondary road frontage); other solid wall 4.0 m\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): code assessable dwelling house only\nStructure scope 'Buildings; building elements incl. garage and carport' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: NO - not listed in Part 1 Table 1.6.1 (only Small Lot Housing Design Code AO3.1, AO4.1, AO7.1/7.2, AO8.1/8.2, AO9.1, AO12.1 are listed); ordinary planning benchmark\nResearcher notes: Table 6.2.2:3 is assessable-only. Dwelling house on lot >= 450 m2 (not hatchet, not in a Schedule 7 plan) is accepted development (Table 5.5:2); otherwise accepted subject to requirements against the LMDR Zone Code (Table 6.2.2:1 has no setback AO) and the Small Lot Housing Design Code / Medium Density Residential Code."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$TRC.trc_lmdr_ao9_1_front@2026-07-21$q$;
