SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 6.2.2:3 PO16/AO16.1-AO16.2; Table 6.2.2:4$q$, 'TABLE', $q$AO16.1 Buildings built to side boundaries have: (a) a maximum height of 3m; and (b) a maximum length of 9m. Note: Built to boundary walls require a 0.00m lot alignment. OR AO16.2 Buildings are set back from a side boundary in accordance with table 6.2.2:4 or the distance of the height of the retaining wall on the side boundary or combination of the height of the retaining wall and a fence, whichever is greater (Figure 1). Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall. || Table 6.2.2:4 – Side Boundary Setbacks | Width of lot frontage || 10.0m - 12.4m | Ground floor (up to 3.5m high) 0.9m | First floor (up to 7.5m high) 0.9m || 12.5m – 14.9m | Ground floor (up to 3.5m high) 1m | First floor (up to 7.5m high) 1m || 15.0m -19.9m | Ground floor (up to 3.5m high) 1m | First floor (up to 7.5m high) 1.5m || 20m + | Ground floor (up to 3.5m high) 1.2m | First floor (up to 7.5m high) 2m || All lots | Second floor (above 7.5m) 2m$q$, 'VERIFIED_VERBATIM', $q$AO16 printed p38 / PDF p38; Table 6.2.2:4 printed p44 / PDF p44$q$, NULL, $q$Low-medium Density Residential Zone Code (6.2.2)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/2/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-06-zone-codes-v29.pdf$q$, $q$Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall.$q$, $q$trc_lmdr_ao16_2_side$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_lmdr_ao16_2_side", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.SIDE", "title": "Table 6.2.2:3 PO16/AO16.1-AO16.2; Table 6.2.2:4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "AO16.1 Buildings built to side boundaries have: (a) a maximum height of 3m; and (b) a maximum length of 9m. Note: Built to boundary walls require a 0.00m lot alignment. OR AO16.2 Buildings are set back from a side boundary in accordance with table 6.2.2:4 or the distance of the height of the retaining wall on the side boundary or combination of the height of the retaining wall and a fence, whichever is greater (Figure 1). Where the retaining wall extends into the site, the setback is measured from the base or top of the retaining wall. || Table 6.2.2:4 – Side Boundary Setbacks | Width of lot frontage || 10.0m - 12.4m | Ground floor (up to 3.5m high) 0.9m | First floor (up to 7.5m high) 0.9m || 12.5m – 14.9m | Ground floor (up to 3.5m high) 1m | First floor (up to 7.5m high) 1m || 15.0m -19.9m | Ground floor (up to 3.5m high) 1m | First floor (up to 7.5m high) 1.5m || 20m + | Ground floor (up to 3.5m high) 1.2m | First floor (up to 7.5m high) 2m || All lots | Second floor (above 7.5m) 2m", "extracted_value": 1, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}, {"level": "ZONE", "zone": "TRC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "trc_lmdr_ao16_2_side", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_setback\", \"operator\": \"conditional\", \"value\": 1, \"uni