SELECT define_rule($q${"rule_id": "TRC.trc_cwea_ao13_1_front", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.FRONTAGE", "title": "Table 7.2.3:1 PO13/AO13.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "AO13.1 All buildings are setback from the primary road frontage not less than: (a) 40m from the Toowoomba Bypass corridor; (b) 20m from the Warrego Highway (other than in the Commercial/Centre Precinct) or the Toowoomba Cecil Plains Road; or (c) 10m otherwise.", "extracted_value": 10, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}], "subjects": ["ANY"], "sources": [{"key": "trc_cwea_ao13_1_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_front_setback\", \"operator\": \"conditional\", \"value\": 10, \"unit\": \"m\", \"conditions\": [\"Toowoomba Bypass corridor: 40 m\", \"Warrego Highway (other than Commercial/Centre Precinct) or Toowoomba Cecil Plains Road: 20 m\", \"otherwise: 10 m\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): code assessable development only\nLocal plan: Charlton Wellcamp Enterprise Area Local Plan\nStructure scope 'All buildings' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO - not listed in Part 1 Table 1.6.1 (only Small Lot Housing Design Code AO3.1, AO4.1, AO7.1/7.2, AO8.1/8.2, AO9.1, AO12.1 are listed); ordinary planning benchmark\nResearcher notes: Industrial enterprise-area local plan; Table 7.2.3:1 is assessable-only. Listed as a benchmark for code-assessable dwelling houses \"where in the Charlton Wellcamp Enterprise Area local plan area\". Rarely relevant to dwelling houses."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$TRC.trc_cwea_ao13_1_front@2026-07-21$q$;
SELECT define_provision($q$TRC_PLANNING_SCHEME_2012@2026-07-21$q$, $q$Table 7.2.3:1 PO14/AO14.1$q$, 'ACCEPTABLE_OUTCOME', $q$AO14.1 Buildings are setback: (a) not less than 40m from any boundary adjoining land outside the Charlton Wellcamp Enterprise Area Local Plan area used for rural purposes; and (b) not less than 70m from Dry Creek, Westbrook Creek or Spring Creek; or otherwise, where not for (a) or (b): (c) a minimum of 5m from any side or rear boundary.$q$, 'VERIFIED_VERBATIM', $q$printed p37 / PDF p37$q$, NULL, $q$Charlton Wellcamp Enterprise Area Local Plan Code (7.2.3)$q$, NULL, $q$https://www.tr.qld.gov.au/files/assets/public/v/1/plan-and-build/planning-for-our-region/planning-scheme/2026-documents/part-07-local-plans-v29.pdf$q$, NULL, $q$trc_cwea_ao14_1_side_rear$q$);
SELECT define_rule($q${"rule_id": "TRC.trc_cwea_ao14_1_side_rear", "instrument_version": "TRC_PLANNING_SCHEME_2012@2026-07-21", "topic": "SETBACK.SIDE", "title": "Table 7.2.3:1 PO14/AO14.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "AO14.1 Buildings are setback: (a) not less than 40m from any boundary adjoining land outside the Charlton Wellcamp Enterprise Area Local Plan area used for rural purposes; and (b) not less than 70m from Dry Creek, Westbrook Creek or Spring Creek; or otherwise, where not for (a) or (b): (c) a minimum of 5m from any side or rear boundary.", "extracted_value": 5, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-07-21", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "TOOWOOMBA"}], "subjects": ["ANY"], "sources": [{"key": "trc_cwea_ao14_1_side_rear", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_setback\", \"operator\": \"conditional\", \"value\": 5, \"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\", \"boundary adjoining rural land outside the local plan area: 40 m\", \"otherwise: 5 m\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): code assessable development only\nLocal plan: Charlton Wellcamp Enterprise Area Local Plan\nStructure scope 'Buildings' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - not listed in Part 1 Table 1.6.1 (only Small Lot Housing Design Code AO3.1, AO4.1, AO7.1/7.2, AO8.1/8.2, AO9.1, AO12.1 are listed); ordinary planning benchmark\nResearcher notes: (b) is a creek buffer (out of scope), kept only because it is part of the same sentence."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$TRC.trc_cwea_ao14_1_side_rear@2026-07-21$q$;

INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$TOOWOOMBA$q$, $q$TRC_PLANNING_SCHEME_2012$q$, 'MEDIUM', $q$Small Lot Housing Design Code AO4.1 refers to "Table 9.3.10:3", but the setback table is 9.3.10:2 (9.3.10:3 is built-to-boundary wall length). Confirm the intended reference with council.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$TOOWOOMBA$q$, $q$TRC_PLANNING_SCHEME_2012$q$, 'MEDIUM', $q$Table 9.3.10:2 lot-width bands overlap ("≤ 12.5 metres" and "> 12 metres"); both give 1.2 m, so the result is the same.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$TOOWOOMBA$q$, $q$TRC_PLANNING_SCHEME_2012$q$, 'MEDIUM', $q$Rural Zone AO1.1 "Non-residential buildings": does it reach a domestic shed ancillary to a dwelling house (Class 10a), or only farm/non-residential buildings?$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$TOOWOOMBA$q$, $q$TRC_PLANNING_SCHEME_2012$q$, 'MEDIUM', $q$Under TLPI 01/2026, building work not associated with an MCU is accepted subject to requirements against "the applicable zone code". It is unclear whether council applies assessable-only zone code tables (e.g. LDR Table 6.2.1:3 setbacks) to such Class 10 building work. The accepted-development parts (Tables 6.2.1:1 / 6.2.2:1) contain no setbacks.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$TOOWOOMBA$q$, $q$TRC_PLANNING_SCHEME_2012$q$, 'MEDIUM', $q$Schedule 7 Approved Plans of Development were not reviewed; they may contain estate-specific setbacks.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$TOOWOOMBA$q$, $q$TRC_PLANNING_SCHEME_2012$q$, 'MEDIUM', $q$QHC adoption: none found in the v29 text; re-check at the next scheme amendment.$q$);
